questions.solution_code:
bisection <- function(f, a, b, tol = 1e-6, max_iter = 100) {
  fa <- f(a)
  fb <- f(b)
  if (fa * fb > 0) stop("Interval neobsahuje zmenu znamenka")
  for (i in seq_len(max_iter)) {
    mid <- (a + b) / 2
    fmid <- f(mid)
    if (abs(fmid) < tol || (b - a) / 2 < tol) return(mid)
    if (fa * fmid < 0) {
      b <- mid
      fb <- fmid
    } else {
      a <- mid
      fa <- fmid
    }
  }
  (a + b) / 2
}

