questions.solution_code:
newton_root <- function(f, df, x0, tol = 1e-8, max_iter = 100) {
  x <- x0
  for (i in seq_len(max_iter)) {
    dfx <- df(x)
    if (abs(dfx) < 1e-14) stop("Derivace je prilis blizko nuly")
    x_new <- x - f(x) / dfx
    if (abs(x_new - x) < tol) return(x_new)
    x <- x_new
  }
  x
}

