questions.solution_code:
lagrange_eval <- function(x_nodes, y_nodes, x0) {
  n <- length(x_nodes)
  res <- 0
  for (i in seq_len(n)) {
    basis <- prod((x0 - x_nodes[-i]) / (x_nodes[i] - x_nodes[-i]))
    res <- res + y_nodes[i] * basis
  }
  res
}

